UPDATE ai_agent_privacy_barrier
SET generation = generation + 1, blocked = TRUE, latest_operation_key = #{operationKey}
WHERE workspace_id = #{workspaceId} AND generation = #{expectedGeneration}
  AND generation < 9223372036854775807

mapper.sql:
s.mission_taint_seq IS NOT NULL
AND (m.mission_run_id IS NOT NULL OR m.author_kind <> 'user' OR m.seq >= s.mission_taint_seq)
AND COALESCE(m.privacy_generation, s.mission_taint_generation) <= #{cutoffGeneration}

mapper.select:
SELECT r.id FROM ai_agent_run r
WHERE r.workspace_id = #{workspaceId} AND r.privacy_generation <= #{cutoffGeneration}
  AND r.id > #{afterId} AND r.id <= #{maxId} AND 
ORDER BY r.id LIMIT #{limit}

SELECT id FROM ai_chat_session
WHERE workspace_id = #{workspaceId} AND mission_taint_generation <= #{cutoffGeneration}
  AND id > #{afterId} AND id <= #{maxId}
ORDER BY id LIMIT #{limit}

SELECT t.id FROM ai_chat_tool_call t
JOIN ai_chat_message m ON m.workspace_id = t.workspace_id AND m.id = t.message_id
JOIN ai_chat_session s ON s.workspace_id = m.workspace_id AND s.id = m.session_id
WHERE t.workspace_id = #{workspaceId} AND s.id = #{sessionId}
  AND t.id > #{afterId} AND t.id <= #{maxId}
  AND 
ORDER BY t.id LIMIT #{limit}

SELECT m.id FROM ai_chat_message m
JOIN ai_chat_session s ON s.workspace_id = m.workspace_id AND s.id = m.session_id
WHERE m.workspace_id = #{workspaceId} AND m.session_id = #{sessionId}
  AND m.id > #{afterId} AND m.id <= #{maxId}
  AND 
ORDER BY m.id LIMIT #{limit}

