DELETE t FROM ai_chat_tool_call t
JOIN ai_chat_message m ON m.workspace_id = t.workspace_id AND m.id = t.message_id
JOIN ai_chat_session s ON s.workspace_id = m.workspace_id AND s.id = m.session_id
WHERE t.workspace_id = #{workspaceId} AND s.id = #{sessionId}
  AND 
  AND t.id IN #{id}

DELETE m FROM ai_chat_message m
JOIN ai_chat_session s ON s.workspace_id = m.workspace_id AND s.id = m.session_id
WHERE m.workspace_id = #{workspaceId} AND m.session_id = #{sessionId}
  AND 
  AND m.id IN #{id}

DELETE t FROM ai_chat_turn t
JOIN ai_chat_session s ON s.workspace_id = t.workspace_id AND s.id = t.session_id
WHERE t.workspace_id = #{workspaceId} AND t.session_id = #{sessionId}
  AND t.mission_run_id IS NULL AND t.status NOT IN ('queued', 'running')
  AND 
  AND t.id IN #{id}

mapper.update:
UPDATE ai_chat_session SET title = #{title}, title_privacy_generation = #{generation},
  last_message_at = COALESCE((SELECT MAX(m.created_at) FROM ai_chat_message m
    WHERE m.workspace_id = #{workspaceId} AND m.session_id = #{sessionId}), created_at)
WHERE workspace_id = #{workspaceId} AND id = #{sessionId}
  AND mission_taint_generation IS NOT NULL AND title_user_set = FALSE
  AND COALESCE(title_privacy_generation, mission_taint_generation) <= #{cutoffGeneration}

UPDATE ai_chat_session SET last_message_at = COALESCE((SELECT MAX(m.created_at)
  FROM ai_chat_message m WHERE m.workspace_id = #{workspaceId} AND m.session_id = #{sessionId}), created_at)
WHERE workspace_id = #{workspaceId} AND id = #{sessionId}

mapper.sql:
(SELECT COUNT(*) FROM ai_chat_message m
 JOIN ai_chat_session s ON s.workspace_id = m.workspace_id AND s.id = m.session_id
 WHERE m.workspace_id = #{workspaceId}
 AND s.id = #{sessionId}
   AND )
+ (SELECT COUNT(*) FROM ai_chat_tool_call t
   JOIN ai_chat_message m ON m.workspace_id = t.workspace_id AND m.id = t.message_id
   JOIN ai_chat_session s ON s.workspace_id = m.workspace_id AND s.id = m.session_id
   WHERE t.workspace_id = #{workspaceId}
   AND s.id = #{sessionId}
     AND )
+ (SELECT COUNT(*) FROM ai_chat_turn t
   JOIN ai_chat_session s ON s.workspace_id = t.workspace_id AND s.id = t.session_id
   WHERE t.workspace_id = #{workspaceId}
   AND s.id = #{sessionId}
     AND )
+ (SELECT COUNT(*) FROM ai_chat_session s
   WHERE s.workspace_id = #{workspaceId} AND s.mission_taint_generation IS NOT NULL
   AND s.id = #{sessionId}
     AND s.title_user_set = FALSE
     AND COALESCE(s.title_privacy_generation, s.mission_taint_generation) <= #{cutoffGeneration})
+ (SELECT COUNT(*) FROM notification n
   JOIN ai_chat_session s ON s.workspace_id = n.workspace_id AND s.id = n.source_id
   WHERE n.workspace_id = #{workspaceId} AND n.source_type = 'ai_chat_session'
   AND s.id = #{sessionId}
     AND s.mission_taint_generation <= #{cutoffGeneration})
+ (SELECT COUNT(*) FROM ai_brief_schedule b
   JOIN ai_chat_session s ON s.workspace_id = b.workspace_id AND s.id = b.pending_session_id
   WHERE b.workspace_id = #{workspaceId}
   AND s.id = #{sessionId}
     AND s.mission_taint_generation <= #{cutoffGeneration})
